import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_data_line(line: str) -> bool:
        s = line.strip()
        if not s:
            return False
        return bool(re.match(r'^\s*\d{1,2}/\d{1,2}/\d{4}\s*,', s))

    start_idx = 0
    for i, line in enumerate(lines):
        if is_data_line(line):
            start_idx = i - 1 if i > 0 else i
            break
        if i == 0 and line.strip():
            start_idx = 0

    if start_idx < 0:
        start_idx = 0

    candidate_text = "\n".join(lines[start_idx:]).lstrip("\n")

    def parse_with_csv_module(s: str) -> List[List[str]]:
        reader = csv.reader(io.StringIO(s), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    rows = parse_with_csv_module(candidate_text)

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    max_width = max([len(header)] + [len(r) for r in data_rows]) if data_rows else len(header)

    def normalize_row(row: List[str], width: int) -> List[str]:
        if len(row) < width:
            return row + [""] * (width - len(row))
        if len(row) > width:
            return row[:width - 1] + [",".join(row[width - 1:])]
        return row

    header = normalize_row(header, max_width)
    data_rows = [normalize_row(r, max_width) for r in data_rows]

    if len(header) == 1 and not data_rows:
        return {"columns": header, "rows": []}

    return {"columns": header, "rows": data_rows}
